package com.example.starter.config;

import com.example.starter.service.ForwarderProperties;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Configuration;

/** 启用转发器配置属性绑定。 */
@Configuration
@EnableConfigurationProperties(ForwarderProperties.class)
public class ForwarderConfig {
}

package com.example.starter.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;

/**
 * 启动恢复：服务（重）启动后把上次进程遗留的 in-flight 消息重置为待发并补发。
 * 依赖 H2 文件库的持久化状态实现跨进程恢复。
 */
@Component
@Order(0)
public class RecoveryRunner implements ApplicationRunner {

    private static final Logger log = LoggerFactory.getLogger(RecoveryRunner.class);

    private final ForwarderServiceImpl service;

    public RecoveryRunner(ForwarderServiceImpl service) {
        this.service = service;
    }

    @Override
    public void run(ApplicationArguments args) {
        int flushed = service.recoverAfterRestart();
        log.info("Startup recovery completed, redispatched {} message(s)", flushed);
    }
}

package com.example.starter.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

/**
 * 周期性补发调度：在线时按优先级/序号顺序补发待发消息，并回收超时 in-flight。
 */
@Component
public class FlushScheduler {

    private static final Logger log = LoggerFactory.getLogger(FlushScheduler.class);

    private final ForwarderService service;

    public FlushScheduler(ForwarderService service) {
        this.service = service;
    }

    @Scheduled(fixedDelayString = "${forwarder.flush-interval-ms:1000}")
    public void tick() {
        try {
            service.flush();
        } catch (Exception e) {
            log.warn("scheduled flush failed: {}", e.getMessage());
        }
    }
}

